use std::fs

struct Parser {
    toks: Vec<string>,
    pos: int,
    out: Vec<string>,
    bad: bool,
}

impl Parser {
    fn peek(self) -> string {
        if self.pos < self.toks.len() as int {
            self.toks[self.pos as usize]
        } else {
            ""
        }
    }

    fn expr(self) {
        self.term()
        while !self.bad && (self.peek() == "+" || self.peek() == "-") {
            let op = self.peek()
            self.pos += 1
            self.term()
            self.out.push(op)
        }
    }

    fn term(self) {
        self.power()
        while !self.bad && (self.peek() == "*" || self.peek() == "/") {
            let op = self.peek()
            self.pos += 1
            self.power()
            self.out.push(op)
        }
    }

    fn power(self) {
        self.atom()
        if !self.bad && self.peek() == "^" {
            self.pos += 1
            self.power()
            self.out.push("^")
        }
    }

    fn atom(self) {
        let t = self.peek()
        if t == "" {
            self.bad = true
        } else if t == "(" {
            self.pos += 1
            self.expr()
            if !self.bad && self.peek() == ")" {
                self.pos += 1
            } else {
                self.bad = true
            }
        } else if t[0..1] >= "0" && t[0..1] <= "9" {
            self.out.push(t)
            self.pos += 1
        } else {
            self.bad = true
        }
    }
}

fn convert(line: string) -> string {
    let mut toks: Vec<string> = []
    let mut num = ""
    for c in line.chars() {
        if c >= '0' && c <= '9' {
            num = num + c.to_string()
        } else {
            if num != "" {
                toks.push(num)
                num = ""
            }
            if c == ' ' || c == '\t' || c == '\r' {
            } else if c == '+' || c == '-' || c == '*' || c == '/' || c == '^' || c == '(' || c == ')' {
                toks.push(c.to_string())
            } else {
                return "error"
            }
        }
    }
    if num != "" {
        toks.push(num)
    }
    let mut p = Parser { toks: toks, pos: 0, out: [], bad: false }
    p.expr()
    if p.bad || p.pos < p.toks.len() as int {
        return "error"
    }
    p.out.join(" ")
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    for line in text.lines() {
        if line.trim() == "" {
            continue
        }
        println(convert(line))
    }
}

